namespace ProMaxx2.QA.Application.Dashboard;

public sealed record DashboardModuleHealth(Guid ModuleId,Guid? ParentModuleId,string ModuleCode,string ModuleName,int SortOrder,int Requirements,int CoveredRequirements,int TestCases,int Executed,int Passed,int Failed,int Blocked,decimal CoveragePercent,decimal ExecutionPercent,decimal PassRate,string Health,int OpenDefects = 0,int CycleCases = 0);
public sealed record DashboardUserPerformance(Guid UserId,string DisplayName,int Executions,int Passed,int Failed,int Blocked,decimal PassRate,DateTime?LastExecutedAt);
public sealed record DashboardStatusSlice(string Status,int Count,string Color);
public sealed record DashboardSeveritySlice(string Severity,int Count,string Color);
public sealed record DashboardSummary(int TotalRequirements,int CoveredRequirements,decimal RequirementCoverage,int TotalCases,int ExecutedCases,decimal ExecutionProgress,int PassedCases,decimal PassRate,int OpenP0,int OpenP1,decimal? OverallScore,int TotalDefects,int OpenDefects,int CriticalDefects,int HighDefects,decimal DefectQuality,string RecommendedDecision,IReadOnlyList<DashboardModuleHealth>Modules,IReadOnlyList<DashboardUserPerformance>Users,IReadOnlyList<DashboardStatusSlice>StatusDistribution,IReadOnlyList<DashboardSeveritySlice>DefectSeverityDistribution,int TotalTestCaseCount,int TestedTestCaseCount,decimal TestCaseProgress,int TotalExecutionCount,DateTime GeneratedAt,string? ProjectName = null,string? ReleaseCode = null,string? ReleaseVersion = null,string? BuildNumber = null,string? DecisionReason = null,int? NewDefectsInBuild = null,int DefectBlockersWithoutRisk = 0,int DefectBlockersWithRisk = 0,int GateCriticalDefects = 0,int GateHighDefects = 0,DashboardDefectInsights? Insights = null);
/// <summary>Defect หนึ่งรายการในมุมมอง Dev (ต้องดูก่อน / รอตรวจซ้ำ) — ไม่ส่งในลิงก์แชร์ที่เปิดแบบ anonymous</summary>
public sealed record DashboardDefectItem(Guid DefectId,string DefectCode,string Title,string Severity,string Status,string? ModuleName,string? FoundInBuild,DateTime CreatedAt,int AgeDays,bool NewInBuild,bool CrmLinked,int ReopenCount,DateTime? ResolvedAt);
/// <summary>Defect ค้างของโมดูลแยกตามความรุนแรง (ModuleId null = ไม่ระบุโมดูล)</summary>
public sealed record DashboardModuleDefects(Guid? ModuleId,string? ModuleCode,string ModuleName,int Critical,int High,int Medium,int Low,int Total);
/// <summary>จำนวน Defect เข้าใหม่ และแก้แล้ว/ปิด ต่อวัน (เวลาไทย)</summary>
public sealed record DashboardDefectTrendPoint(DateOnly Date,int Created,int Closed);
/// <summary>ข้อมูล Defect ของมุมมองผู้บริหาร/Dev — ขอบเขตเดียวกับการ์ด Defect ของ Dashboard (เลือก Build = ค้าง ณ Build นี้ รวม Build ก่อนหน้า)</summary>
public sealed record DashboardDefectInsights(int Open,int Unresolved,int InProgress,int AwaitingRetest,int Critical,int High,int Medium,int Low,int? NewInBuild,int? NewInBuildHigh,int Closed,int Rejected,int Reopened,int CrmLinked,decimal? AverageAgeDays,IReadOnlyList<int>AgeBuckets,IReadOnlyList<DashboardModuleDefects>Modules,IReadOnlyList<DashboardDefectTrendPoint>Trend,IReadOnlyList<DashboardDefectItem>Attention,IReadOnlyList<DashboardDefectItem>AwaitingRetestItems,DateTime GeneratedAt);
public sealed record DashboardShareScope(string Code,Guid? ProjectId,Guid? ReleaseId,Guid? BuildId,DateTime ExpiresAt);
public sealed record DashboardTimelineRelease(Guid ReleaseId,string ReleaseCode,string Version,string Status,DateOnly?PlannedReleaseDate,DateOnly?ActualReleaseDate);
public sealed record DashboardTimelineCycle(Guid TestCycleId,string CycleCode,string CycleName,string Status,DateTime?StartDate,DateTime?EndDate,decimal ProgressPercent);
public sealed record DashboardTimeline(IReadOnlyList<DashboardTimelineRelease>Releases,IReadOnlyList<DashboardTimelineCycle>Cycles);
public interface IDashboardRepository{Task<DashboardSummary>GetAsync(Guid?projectId,Guid?releaseId,Guid?buildId,CancellationToken ct);Task<DashboardTimeline>GetTimelineAsync(Guid?projectId,Guid?releaseId,Guid?buildId,CancellationToken ct);Task<DashboardDefectInsights>GetDefectInsightsAsync(Guid?projectId,Guid?releaseId,Guid?buildId,Guid?assigneeUserId,bool includeItems,CancellationToken ct);Task<DashboardShareScope>CreateShareAsync(Guid?projectId,Guid?releaseId,Guid?buildId,DateTime expiresAt,CancellationToken ct);Task<DashboardShareScope?>FindShareAsync(string code,CancellationToken ct);Task<bool>RevokeShareAsync(string code,IReadOnlyCollection<Guid>allowedProjectIds,CancellationToken ct);}
public sealed class DashboardService(IDashboardRepository repository){public Task<DashboardSummary>GetAsync(Guid?p,Guid?r,Guid?b,CancellationToken ct)=>repository.GetAsync(p,r,b,ct);public Task<DashboardTimeline>GetTimelineAsync(Guid?p,Guid?r,Guid?b,CancellationToken ct)=>repository.GetTimelineAsync(p,r,b,ct);public Task<DashboardDefectInsights>GetDefectInsightsAsync(Guid?p,Guid?r,Guid?b,Guid?assignee,bool includeItems,CancellationToken ct)=>repository.GetDefectInsightsAsync(p,r,b,assignee,includeItems,ct);public Task<DashboardShareScope>CreateShareAsync(Guid?p,Guid?r,Guid?b,DateTime expiresAt,CancellationToken ct)=>repository.CreateShareAsync(p,r,b,expiresAt,ct);public Task<DashboardShareScope?>FindShareAsync(string code,CancellationToken ct)=>repository.FindShareAsync(code,ct);public Task<bool>RevokeShareAsync(string code,IReadOnlyCollection<Guid>allowedProjectIds,CancellationToken ct)=>repository.RevokeShareAsync(code,allowedProjectIds,ct);}
